esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// node_filesystem_readonly is a gauge: 1 = the kernel remounted the filesystem read-only.
// Same metric and aggregation as the "Filesystem Read-Only Status" dashboard panel.
| STATS
    `Read Only` = MAX(LAST_OVER_TIME(node_filesystem_readonly)),
    `Device Error` = MAX(LAST_OVER_TIME(node_filesystem_device_error))
  BY resource.attributes.supabase_project_ref, attributes.mountpoint, attributes.device
| WHERE `Read Only` == 1
// One row per mounted filesystem, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.mountpoint, " / ", attributes.device)
